// Rebuild the original medical introduction from its SVG scenes and ElevenLabs audio.
// Requires Playwright, Chromium, ffmpeg and ffprobe on the build machine.
const {chromium}=require('playwright');const fs=require('node:fs');const path=require('node:path');const os=require('node:os');const {execFileSync}=require('node:child_process');
(async()=>{const root=path.resolve(__dirname,'../..'),assets=path.join(root,'public/assets'),tmp=fs.mkdtempSync(path.join(os.tmpdir(),'tuuvo-medical-'));
const scenes=['med-preparo','med-exploracao','med-reflexao'];const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH||'/usr/bin/chromium'});
try{const page=await browser.newPage({viewport:{width:1280,height:720}});for(const scene of scenes){await page.setContent('<style>html,body{margin:0;background:#e7eee7}svg{width:1280px;height:720px;display:block}</style>'+fs.readFileSync(path.join(assets,scene+'.svg'),'utf8'));await page.screenshot({path:path.join(tmp,scene+'.png')})}}finally{await browser.close()}
try{const durations=[];for(let i=0;i<3;i++){const audio=path.join(assets,`narration-medical/segment-${i+1}.mp3`);const duration=Number(JSON.parse(execFileSync('ffprobe',['-v','error','-show_entries','format=duration','-of','json',audio])).format.duration)+.8;durations.push(duration);const frames=Math.ceil(duration*25);execFileSync('ffmpeg',['-y','-hide_banner','-loglevel','error','-loop','1','-i',path.join(tmp,scenes[i]+'.png'),'-i',audio,'-vf',`zoompan=z='min(zoom+0.0005,1.1)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=${frames}:s=1280x720:fps=25,format=yuv420p`,'-af','loudnorm=I=-16:TP=-1.5:LRA=7,apad=pad_dur=0.8','-t',String(duration),'-c:v','libx264','-profile:v','baseline','-level','3.1','-preset','medium','-crf','24','-c:a','aac','-b:a','128k','-ar','48000','-ac','1',path.join(tmp,`clip-${i}.mp4`)])}
fs.writeFileSync(path.join(tmp,'concat.txt'),[0,1,2].map(i=>`file '${path.join(tmp,`clip-${i}.mp4`)}'`).join('\n'));execFileSync('ffmpeg',['-y','-hide_banner','-loglevel','error','-f','concat','-safe','0','-i',path.join(tmp,'concat.txt'),'-c','copy','-movflags','+faststart',path.join(assets,'medical-intro.mp4')]);
const texts=['Ana voltou para uma conversa de acompanhamento.\nEla não conseguiu seguir o combinado\ne está preocupada.','Nesta consulta simulada, você acompanha\num estudante sob supervisão. Suas perguntas\npodem revelar informações que ainda não apareceram.','Prepare o encontro, escute e construa\nos próximos passos com Ana. Ao final, reveja\nas decisões nesta história fictícia.'];const stamp=t=>{let ms=Math.round(t*1000);return `${String(Math.floor(ms/3600000)).padStart(2,'0')}:${String(Math.floor(ms/60000)%60).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}.${String(ms%1000).padStart(3,'0')}`};let current=0;let vtt='WEBVTT\n\n';durations.forEach((d,i)=>{vtt+=`${stamp(current)} --> ${stamp(current+d)}\n${texts[i]}\n\n`;current+=d});fs.writeFileSync(path.join(assets,'medical-intro.vtt'),vtt.trimEnd()+'\n');console.log(JSON.stringify({provider:'ElevenLabs',scenes:3,duration:current}));
}finally{fs.rmSync(tmp,{recursive:true,force:true})}
})().catch(error=>{console.error(error.message);process.exit(1)});
